// The 'Hello World' of embedded: blink an LED
// Runs on Arduino Uno, Nano, Mega, ESP32, etc.

const int LED_PIN = 13;  // Built-in LED on most Arduino boards

void setup() {
  // Called once at power-on or reset
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);
  Serial.println("Embedded system started!");
}

void loop() {
  // Called repeatedly, forever
  digitalWrite(LED_PIN, HIGH);  // Turn LED on
  Serial.println("LED ON");
  delay(1000);                  // Wait 1 second

  digitalWrite(LED_PIN, LOW);   // Turn LED off
  Serial.println("LED OFF");
  delay(1000);
}
